package de.tum.cit.aet.sorting;

import java.util.Objects;

/**
 * Represents a colour with a name and a hue value.
 */
public class Color implements Comparable<Color> {
    private String name;
    private int hue; // 0-360 degrees

    public Color() {
        // default constructor for serialization / tests
    }

    public Color(String name, int hue) {
        this.name = name;
        this.hue = hue;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public int getHue() {
        return hue;
    }

    public void setHue(int hue) {
        this.hue = hue;
    }

    @Override
    public int compareTo(Color o) {
        return Integer.compare(this.hue, o.hue);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Color color = (Color) o;
        return hue == color.hue && Objects.equals(name, color.name);
    }

    @Override
    public int hashCode() {
        return Objects.hash(name, hue);
    }

    @Override
    public String toString() {
        return "Color{" + "name='" + name + '\'' + ", hue=" + hue + '}';
    }
}

